"""VLM Client for spatial reasoning and UI coordinate prediction using Google GenAI SDK."""

import json
import logging
import os
from typing import List, Optional
from pydantic import BaseModel, Field
from igris.perception.screen import ScreenFrame

logger = logging.getLogger("igris.brain.vlm_client")


class VisualAction(BaseModel):
    """Structured action generated by VLM for desktop manipulation."""
    action_type: str = Field(
        ...,
        description="Action to perform: 'click', 'double_click', 'right_click', 'type', 'scroll_down', 'scroll_up', 'wait', 'finished'",
    )
    normalized_x: int = Field(default=500, description="Horizontal coordinate on a 0-1000 normalized scale")
    normalized_y: int = Field(default=500, description="Vertical coordinate on a 0-1000 normalized scale")
    text_input: Optional[str] = Field(default=None, description="Text to type if action_type is 'type'")
    reasoning: str = Field(..., description="Explanation of why this action was chosen")
    task_completed: bool = Field(default=False, description="Whether the user goal is fully accomplished")


SYSTEM_PROMPT = """You are Igris, an autonomous Computer-Operating AI Agent.
You observe the user's desktop screen and decide the next mouse, keyboard, or terminal action to accomplish the user's goal.

COORDINATE SYSTEM:
- Return coordinates normalized on a 0 to 1000 scale.
- (0, 0) is top-left, (1000, 1000) is bottom-right.
- (500, 500) is the exact center of the screen.
- Aim for the visual center of buttons, inputs, icons, or links.

ACTION TYPES:
- 'click': Left-click at (normalized_x, normalized_y).
- 'double_click': Double-click at (normalized_x, normalized_y).
- 'right_click': Right-click at (normalized_x, normalized_y).
- 'type': Type text specified in 'text_input' into focused field.
- 'type_and_enter': Type text specified in 'text_input' and press Enter/Return.
- 'press_key': Press key specified in 'text_input' (e.g. 'Return', 'Escape', 'Tab', 'BackSpace').
- 'hotkey': Trigger shortcut specified in 'text_input' (e.g. 'ctrl+t', 'ctrl+w', 'ctrl+l').
- 'scroll_down': Scroll down at coordinate.
- 'scroll_up': Scroll up at coordinate.
- 'terminal': Execute non-destructive shell command in 'text_input' (e.g. 'google-chrome "https://youtube.com" &' or 'firefox &') to launch applications.
- 'wait': Wait for page/app to load.
- 'finished': The user's goal has been completely achieved.

OUTPUT FORMAT:
Return pure, valid JSON matching the following schema:
{
  "action_type": "click",
  "normalized_x": 450,
  "normalized_y": 320,
  "text_input": null,
  "reasoning": "Clicking the search input field to enter search query",
  "task_completed": false
}
"""


DEFAULT_MODELS_CASCADE = [
    "gemini-3.1-flash-lite",
    "gemini-3.5-flash-lite",
    "gemini-3.5-flash",
    "gemini-3.8-flash",
]


class VLMClient:
    """Interfaces with multimodal Vision-Language Models for desktop spatial reasoning."""

    def __init__(
        self,
        api_key: Optional[str] = None,
        model_name: Optional[str] = None,
        fallback_models: Optional[List[str]] = None,
    ):
        if not api_key and "GEMINI_API_KEY" not in os.environ:
            from igris.core.config import AppConfig
            AppConfig.load()

        self.api_key = api_key or os.getenv("GEMINI_API_KEY")
        self.model_name = model_name or os.getenv("GEMINI_MODEL", "gemini-3.5-flash")
        self.fallback_models = fallback_models or list(DEFAULT_MODELS_CASCADE)
        self._client = None

    def _get_client(self):
        """Lazy initialization of google-genai client."""
        if self._client is None:
            if not self.api_key:
                raise ValueError("GEMINI_API_KEY not configured. Set environment variable or pass to VLMClient.")
            from google import genai
            self._client = genai.Client(api_key=self.api_key)
        return self._client

    def predict_action(
        self,
        frame: ScreenFrame,
        task_goal: str,
        recent_history: Optional[List[str]] = None,
    ) -> VisualAction:
        """Analyze screen frame and predict next computer action."""
        client = self._get_client()

        # Prepare image bytes
        image_bytes = frame.to_bytes(format="JPEG", quality=85)

        history_context = ""
        if recent_history:
            history_context = "Recent Action History:\n" + "\n".join(f"- {h}" for h in recent_history[-5:])

        prompt = f"""Goal: {task_goal}

{history_context}

Observe the current screen state and output the single next optimal action in JSON format.
"""

        from google.genai import types

        # Determine cascade of models to try
        candidate_models = [self.model_name]
        for m in self.fallback_models:
            if m not in candidate_models:
                candidate_models.append(m)

        last_error = None
        for idx, current_model in enumerate(candidate_models):
            try:
                logger.debug("Dispatching frame to VLM model: %s", current_model)
                response = client.models.generate_content(
                    model=current_model,
                    contents=[
                        types.Part.from_bytes(data=image_bytes, mime_type="image/jpeg"),
                        types.Part.from_text(text=prompt),
                    ],
                    config=types.GenerateContentConfig(
                        system_instruction=SYSTEM_PROMPT,
                        temperature=0.1,
                        response_mime_type="application/json",
                    ),
                )
                response_text = response.text or "{}"
                return self._parse_response(response_text)
            except Exception as e:
                last_error = e
                next_model = candidate_models[idx + 1] if idx + 1 < len(candidate_models) else None
                if next_model:
                    logger.warning(
                        "VLM model '%s' encountered error: %s. Falling back to next model '%s'...",
                        current_model,
                        e,
                        next_model,
                    )
                else:
                    logger.error("All VLM models in cascade exhausted. Final error: %s", e)

        if last_error:
            raise last_error
        raise RuntimeError("No VLM model succeeded in generating an action.")

    def _parse_response(self, text: str) -> VisualAction:
        """Parse model JSON response into VisualAction model."""
        # Strip code markdown fences if present
        clean = text.strip()
        if clean.startswith("```"):
            if clean.startswith("```json"):
                clean = clean[7:]
            else:
                clean = clean[3:]
        clean = clean.strip()
        if clean.endswith("```"):
            clean = clean[:-3]
        clean = clean.strip()

        try:
            data = json.loads(clean)
            return VisualAction(**data)
        except Exception as e:
            logger.error("Failed to parse VLM response as VisualAction: %s. Raw: %s", e, text)
            # Safe fallback action
            return VisualAction(
                action_type="wait",
                normalized_x=500,
                normalized_y=500,
                reasoning=f"Parse fallback due to invalid JSON: {e}",
                task_completed=False,
            )

